              (pTraceComponent->pOnTraceFinishedContext,pTraceComponent->dwCompletionArgument0,
               pTraceComponent->dwCompletionArgument1);
                    /* Consume the callback by clearing only the function pointer; context and
                       arguments remain. */
    pTraceComponent->pOnTraceFinished = (void *)0x0;
  }
  return;
}
